const fs   = require('fs');
const util = require('util');

// ── 1. Callbacks (original Node.js style) ──
fs.readFile('./data.json', 'utf8', (err, data) => {
    if (err) { console.error('Callback error:', err.message); return; }
    console.log('Callback result:', JSON.parse(data).length, 'items');

    // Nested callbacks — "callback hell"
    fs.readFile('./notes.txt', 'utf8', (err2, notes) => {
        if (err2) return console.error(err2.message);
        console.log('Notes:', notes.slice(0, 30));
    });
});

// ── 2. util.promisify — callbacks → Promises ──
const readFile = util.promisify(fs.readFile);

readFile('./data.json', 'utf8')
    .then(data => console.log('Promise:', JSON.parse(data).length, 'items'))
    .catch(err => console.error('Promise error:', err.message));

// ── 3. async/await (modern — use this) ──
async function loadFiles() {
    try {
        // Sequential: wait for each
        const data  = await readFile('./data.json', 'utf8');
        const notes = await readFile('./notes.txt',  'utf8');
        console.log('async/await: data items:', JSON.parse(data).length);
        console.log('async/await: notes:', notes.slice(0, 30));

        // Parallel: run concurrently
        const [d, n] = await Promise.all([
            readFile('./data.json', 'utf8'),
            readFile('./notes.txt',  'utf8'),
        ]);
        console.log('Parallel: both loaded.');
    } catch (err) {
        console.error('Async error:', err.message);
    }
}

loadFiles();
